// Table
table_width = 1200;            // [400:50:2400]
table_depth = 700;             // [300:25:1400]
table_height = 750;            // [400:25:1100]
top_thickness = 30;            // [10:2:60]
top_corner_radius = 15;        // [0:5:60]
leg_size = 50;                 // [25:5:90]
leg_inset = 25;                // [0:5:120]
leg_corner_radius = 6;         // [0:1:20]
apron_height = 80;             // [0:5:200]
apron_thickness = 20;          // [10:2:40]
apron_inset = 10;              // [0:5:60]
top_color = "Sienna";
leg_color = "SaddleBrown";
apron_color = "SaddleBrown";
resolution = 24;
$fn = resolution;
leg_height = table_height - top_thickness;

module rounded_box(w, d, h, r) {
  effective_r = min(r, w / 2 - 0.01, d / 2 - 0.01);
  if (effective_r <= 0) {
    cube([w, d, h]);
  } else {
    linear_extrude(height = h)
      translate([effective_r, effective_r])
      offset(r = effective_r)
      square([w - 2 * effective_r, d - 2 * effective_r]);
  }
}

color(top_color)
  translate([0, 0, leg_height])
  rounded_box(table_width, table_depth, top_thickness, top_corner_radius);

color(leg_color)
  for (x = [leg_inset, table_width - leg_inset - leg_size])
    for (y = [leg_inset, table_depth - leg_inset - leg_size])
      translate([x, y, 0])
        rounded_box(leg_size, leg_size, leg_height, leg_corner_radius);

if (apron_height > 0) {
  apron_z = leg_height - apron_height;
  inner_x = leg_inset + leg_size;
  inner_w = table_width - 2 * (leg_inset + leg_size);
  inner_y = leg_inset + leg_size;
  inner_d = table_depth - 2 * (leg_inset + leg_size);
  color(apron_color) {
    translate([inner_x, leg_inset + apron_inset, apron_z])
      cube([inner_w, apron_thickness, apron_height]);
    translate([inner_x, table_depth - leg_inset - apron_inset - apron_thickness, apron_z])
      cube([inner_w, apron_thickness, apron_height]);
    translate([leg_inset + apron_inset, inner_y, apron_z])
      cube([apron_thickness, inner_d, apron_height]);
    translate([table_width - leg_inset - apron_inset - apron_thickness, inner_y, apron_z])
      cube([apron_thickness, inner_d, apron_height]);
  }
}
